// Farsi translation of LIMERENCE's Act III room prose (beats, choice
// text/hint/outcome, field notes, plain-language explanations). Registered
// under version 'v2'. Follows the structural pattern established by Act I's
// src/packs/limerence/text/fa-rooms.ts and Act II's fa-rooms-act2.ts — see
// CLAUDE.md's "Translating content" rule: every line here was translated
// against the room's actual beats and each choice's stakes, not
// word-for-word. Act III's cast is 25-30, adults in long-established
// partnerships, engaged or married — a still franker, more settled register
// than Act II's; the prose leans into the exhaustion and precision of
// people who have been together long enough to know each other's
// silences, not into teenage drama or new-relationship hedging. Unlike the
// Czech pass, Dana (the recurring partner across most of this act) and Sam
// (the-veto) need no special grammatical handling: Farsi has no gendered
// third-person pronouns or verb conjugation, so "او" and every verb form
// used for any character stay gender-neutral by default — the same
// non-issue Jules was in the Farsi Act II pass. Proper names (Dana, Sam,
// Petra, Rowan, Dr. Weiss) are transliterated into Persian script, matching
// Act I/II's treatment of Sara/Mira/Alena/Nadia/Jules. "The Porter" stays
// "دربان" throughout, never "نگهبان" (ANAMNESIS's own guide). "Chattam"
// stays transliterated ("چاتم"), not translated. Numerals: Western digits
// for citation years in field-note thinkers lines, Persian digits for
// in-fiction numbers within narrative prose (times, counts, ages), matching
// established convention. Room title/doorHint/teaser fields are not
// translated anywhere in this project.
import { register, registerAll } from '../../../engine/text/resolver';
import {
  roomBeatKey,
  roomChoiceHintKey,
  roomChoiceOutcomeKey,
  roomChoiceTextKey,
  roomExplanationKey,
  roomNoteBodyKey,
  roomNoteThinkersKey,
  roomNoteTitleKey,
} from '../../../engine/text/keys';
import type { RunState } from '../../../engine/schema';
import { pickShadowMoments } from '../../../engine/gameState';

/** Mirrors act3.ts's own seedSplit/seedSplit2 — same deterministic 50/50
 * splits on the run's doorSeed, so a translated branch always matches the
 * English branch it stands in for. Two independently-offset variants so
 * two branch points in the same room don't always land the same way. */
function seedSplit(s: RunState): boolean {
  return ((s.doorSeed ?? 0) * 2654435761) % 2 === 0;
}
function seedSplit2(s: RunState): boolean {
  return ((s.doorSeed ?? 0) * 40503 + 17) % 2 === 0;
}

